using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;

public partial class WorldTerrainOperations
{
    public Settings tunnels_plan(RefCounted session,string id,Resource source)
    {
        string terrainId=source.Get("terrain_id").AsString();var original=_documents.terrain(session.Get("document").As<Resource>(),terrainId);bool needed=false;var roads=source.Get("roads").AsGodotArray();foreach(var value in roads){var road=value.AsGodotDictionary();needed|=Get(road,"enabled",true).AsBool()&&Get(road,"mode","Ground").AsString()=="Tunnel";}if(original!=null)foreach(var value in original.Get("caves").AsGodotArray()){var cave=value.As<Resource>();needed|=cave.HasMeta("world_road_owner")&&cave.GetMeta("world_road_owner").AsString()==id;}if(!needed)return Failure("");var info=context(session,id,source);if(info["error"].AsString().Length>0)return info;var caves=original!.Get("caves").AsGodotArray().Duplicate();caves.Clear();var portals=new Settings();var frames=new Settings();foreach(var value in original.Get("caves").AsGodotArray()){var cave=value.As<Resource>();if(!cave.HasMeta("world_road_owner")||cave.GetMeta("world_road_owner").AsString()!=id)caves.Add(cave);}
        foreach(var value in roads)
        {
            var road=value.AsGodotDictionary();if(!Get(road,"enabled",true).AsBool()||Get(road,"mode","Ground").AsString()!="Tunnel")continue;var points=_geometry.sample(road["points"].AsVector3Array(),.5);double width=road["width"].AsDouble(),height=width*.65+2,radius=Math.Sqrt(Math.Pow(width*.5+.35,2)+Math.Pow(height*.5,2));foreach(var endpoint in new[]{points[0],points[^1]}){var ground=sample(info,new Vector2(endpoint.X,endpoint.Z));if(ground.Count==0||ground["height"].AsDouble()>endpoint.Y+.3)return Failure("Extend both tunnel endpoints beyond the hillside so the entrances can open to the surface.");}
            var portalPoints=new List<Vector3>();var portalFrames=new Godot.Collections.Array();bool lastInside=false;var previous=points[0];double previousDepth=-1;foreach(var point in points){var ground=sample(info,new Vector2(point.X,point.Z));if(ground.Count==0)return Failure("The tunnel must stay within its referenced terrain.");double depth=ground["height"].AsDouble()-point.Y-height*.5-radius+.3;bool inside=depth>0;if(inside!=lastInside){double t=Math.Clamp(-previousDepth/Math.Max(.00001,Math.Abs(depth-previousDepth))*(depth>previousDepth?1:-1),0,1);var entrance=previous.Lerp(point,(float)t);portalPoints.Add(entrance);portalFrames.Add(new Settings {["position"]=entrance,["direction"]=(point-previous).Normalized()});lastInside=inside;}previous=point;previousDepth=depth;}
            if(portalPoints.Count<2)return Failure("This road does not pass beneath enough terrain to form a tunnel. Use a ground road or lower its elevation.");portals[road["id"]]=portalPoints.ToArray();frames[road["id"]]=portalFrames;var path=new List<Vector3>();var toGround=info["to_ground"].AsTransform3D();var scale=toGround.Basis.Scale.Abs();double localRadius=radius*Math.Max(scale.X,Math.Max(scale.Y,scale.Z));for(int index=0;index<points.Length;index++){if(index>0&&index<points.Length-1&&(points[index]-points[index-1]).Normalized().Dot((points[index+1]-points[index]).Normalized())>.9995)continue;path.Add(toGround*(points[index]+Vector3.Up*(float)(height*.5)));}path[0]-=(path[1]-path[0]).Normalized()*(float)localRadius;path[^1]+=(path[^1]-path[^2]).Normalized()*(float)localRadius;var cave=new KiwiTerrainCave();cave.Set("cave_id",id+":tunnel:"+road["id"].AsString());cave.Set("title","Road tunnel · "+Get(road,"name","Road").AsString());cave.Set("radius",localRadius);cave.Set("radius_variation",0.0);cave.Set("roughness",0.0);cave.Set("junction_smoothing",.1);cave.Get("paths").AsGodotArray().Add(path.ToArray());cave.SetMeta("world_road_owner",id);caves.Add(cave);
        }
        return new Settings {["error"]="",["id"]=source.Get("terrain_id"),["source"]=original,["signature"]=_terrain.signature(original),["portal_points"]=portals,["portal_frames"]=frames,["settings"]=new Settings {["caves"]=caves}};
    }
}
